itionalAnalyses": "ALLOWED"|"REQUIRED"|"NOT_ALLOWED" }, "aggregation": { "aggregateColumns": [ { "columnNames": ["string", ...], "function": "SUM"|"SUM_DISTINCT"|"COUNT"|"COUNT_DISTINCT"|"AVG" } ... ], "joinColumns": ["string", ...], "joinRequired": "QUERY_RUNNER", "allowedJoinOperators": ["OR"|"AND", ...], "dimensionColumns": ["string", ...], "scalarFunctions": ["ABS"|"CAST"|"CEILING"|"COALESCE"|"CONVERT"|"CURRENT_DATE"|"DATEADD"|"EXTRACT"|"FLOOR"|"GETDATE"|"LN"|"LOG"|"LOWER"|"ROUND"|"RTRIM"|"SQRT"|"SUBSTRING"|"TO_CHAR"|"TO_DATE"|"TO_NUMBER"|"TO_TIMESTAMP"|"TRIM"|"TRUNC"|"UPPER", ...], "outputConstraints": [ { "columnName": "string", "minimum": integer, "type": "COUNT_DISTINCT" } ... ], "additionalAnalyses": "ALLOWED"|"REQUIRED"|"NOT_ALLOWED" }, "custom": { "allowedAnalyses": ["string", ...], "allowedAnalysisProviders": ["string", ...], "additionalAnalyses": "ALLOWED"|"REQUIRED"|"NOT_ALLOWED", "disallowedOutputColumns": ["string", ...], "differentialPrivacy": { "columns": [ { "name": "string" } ... ] }, "aggregationThresholds": [ { "identityColumns": ["string", ...], "minimumIdentityCount": integer, "type": "COUNT_DISTINCT", "outputColumnThresholds": [ { "outputColumnName": "string", "minimumIdentityCount": integer } ... ], "allowedAggregateExpressionType": "COLUMNS_ONLY"|"ANY_EXPRESSION" } ... ], "comparisonControls": { "allowedLiteralComparisonColumns": ["string", ...], "allowedColumnComparisonColumns": ["string", ...] }, "allowedResultReceivers": ["string", ...], "allowedAdditionalAnalyses": ["string", ...] } } }
    /// </summary>
    [CliOption("--analysis-rule-policy")]
    public string? AnalysisRulePolicy { get; private init; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

    /// <summary>Appends diagnostic members without exposing command option values.</summary>
    /// <param name="builder">The builder receiving the record members.</param>
    /// <returns>True because a redaction marker was appended.</returns>
    protected override bool PrintMembers(global::System.Text.StringBuilder builder)
    {
        builder.Append("Options = <redacted>");
        return true;
    }

